files.content:
:root {
  --bg: #0f1724;
  --panel: #16223a;
  --panel-2: #1d2b46;
  --line: #2b3a58;
  --text: #e6edf7;
  --muted: #93a4c1;
  --accent: #3c8dff;
  --accent-2: #2b6fd8;
  --ok: #35c07a;
  --warn: #f0a94a;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: "PingFang SC", "Microsoft YaHei", "Helvetica Neue", Arial, sans-serif;
  background: radial-gradient(1200px 600px at 15% -10%, #1b2b48 0%, var(--bg) 60%);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 14px 28px;
  background: rgba(15, 23, 36, 0.92);
  border-bottom: 1px solid var(--line);
}

.brand { display: flex; align-items: baseline; gap: 10px; }
.logo {
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 2px;
  color: #fff;
}
.brand-sub { color: var(--muted); font-size: 13px; }

.topnav { display: flex; gap: 6px; margin-left: 12px; }
.topnav a {
  color: var(--muted);
  text-decoration: none;
  font-size: 14px;
  padding: 6px 12px;
  border-radius: 6px;
}
.topnav a:hover { color: var(--text); background: var(--panel); }
.topnav a.active { color: #fff; background: var(--panel-2); }

.userbox {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 14px;
  color: var(--muted);
}

.page {
  flex: 1;
  width: 100%;
  max-width: 1040px;
  margin: 0 auto;
  padding: 28px 20px 48px;
}

.card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 26px 28px;
}

.login-card { max-width: 420px; margin: 40px auto; }
.login-card h1 { margin: 0 0 6px; font-size: 22px; }
.hint { color: var(--muted); font-size: 13px; margin: 0 0 20px; }

label {
  display: block;
  font-size: 13px;
  color: var(--muted);
  margin: 14px 0 6px;
}

input {
  width: 100%;
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid var(--line);
  background: #101a2c;
  color: var(--text);
  font-size: 14px;
}
input:focus { outline: none; border-color: var(--accent); }

button {
  cursor: pointer;
  font-size: 14px;
  border-radius: 8px;
  border: 1px solid transparent;
  padding: 10px 16px;
}
button.primary {
  width: 100%;
  margin-top: 22px;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
  letter-spacing: 2px;
}
button.primary:hover { background: var(--accent-2); }
button.ghost {
  background: transparent;
  border-color: var(--line);
  color: var(--text);
  padding: 7px 12px;
}
button.ghost:hover { border-color: var(--accent); color: #fff; }

.msg { min-height: 20px; font-size: 13px; margin: 12px 0 0; color: var(--warn); }
.msg.ok { color: var(--ok); }

.toolbar {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 14px;
}
.toolbar h2 { font-size: 18px; margin: 0; }
.toolbar-actions { margin-left: auto; display: flex; gap: 10px; }
.toolbar-actions input { width: 220px; }

.filetable {
  width: 100%;
  border-collapse: collapse;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
  font-size: 14px;
}
.filetable th, .filetable td {
  text-align: left;
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
}
.filetable th { background: var(--panel-2); color: var(--muted); font-weight: 500; }
.filetable tr:last-child td { border-bottom: none; }
.filetable td.empty { color: var(--muted); text-align: center; padding: 24px; }

.link-btn {
  background: transparent;
  border: none;
  color: var(--accent);
  padding: 0 8px 0 0;
  font-size: 14px;
}
.link-btn:hover { text-decoration: underline; }

.panel {
  margin-top: 22px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
}
.panel-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  background: var(--panel-2);
  border-bottom: 1px solid var(--line);
}
.panel-head h3 { margin: 0; font-size: 15px; }
.panel-file { margin-left: auto; color: var(--muted); font-size: 13px; }

pre.preview {
  margin: 0;
  padding: 16px;
  min-height: 140px;
  max-height: 340px;
  overflow: auto;
  font-family: Consolas, Menlo, monospace;
  font-size: 13px;
  line-height: 1.6;
  white-space: pre-wrap;
  color: #cfe0f7;
}

.footer {
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 12px;
  text-align: center;
  padding: 14px;
}

/* 云巢文档中心 —— 本地模拟交互逻辑
   所有请求仅指向同源 mock 路由：
     POST /api/login    -> 登录
     GET  /api/files    -> 文件列表
     GET  /api/audit    -> 审计日志
     GET  /api/download -> 文件内容（?file= 指定文件名）
*/

(function () {
  "use strict";

  var loginView = document.getElementById("loginView");
  var workspaceView = document.getElementById("workspaceView");
  var loginForm = document.getElementById("loginForm");
  var loginMsg = document.getElementById("loginMsg");
  var currentUser = document.getElementById("currentUser");
  var logoutBtn = document.getElementById("logoutBtn");
  var fileRows = document.getElementById("fileRows");
  var searchBox = document.getElementById("searchBox");
  var reloadBtn = document.getElementById("reloadBtn");
  var previewName = document.getElementById("previewName");
  var previewBody = document.getElementById("previewBody");

  var allFiles = [];

  function text(el, value) {
    if (el) { el.textContent = value; }
  }

  function formatSize(bytes) {
    if (!bytes && bytes !== 0) { return "-"; }
    var units = ["B", "KB", "MB", "GB"];
    var i = 0;
    var n = bytes;
    while (n >= 1024 && i < units.length - 1) { n = n / 1024; i += 1; }
    return (i === 0 ? n : n.toFixed(1)) + " " + units[i];
  }

  function getJSON(url) {
    return fetch(url, {
      method: "GET",
      headers: { "Accept": "application/json" }
    }).then(function (res) {
      if (!res.ok) { throw new Error("HTTP " + res.status); }
      return res.json();
    });
  }

  function renderRows(list) {
    fileRows.innerHTML = "";
    if (!list.length) {
      var empty = document.createElement("tr");
      var cell = document.createElement("td");
      cell.colSpan = 4;
      cell.className = "empty";
      cell.textContent = "没有匹配的文件";
      empty.appendChild(cell);
      fileRows.appendChild(empty);
      return;
    }
    list.forEach(function (item) {
      var tr = document.createElement("tr");

      var name = document.createElement("td");
      name.textContent = item.name;

      var size = document.createElement("td");
      size.textContent = formatSize(item.size);

      var updated = document.createElement("td");
      updated.textContent = item.updated || "-";

      var actions = document.createElement("td");
      var viewBtn = document.createElement("button");
      viewBtn.type = "button";
      viewBtn.className = "link-btn";
      viewBtn.textContent = "预览";
      viewBtn.addEventListener("click", function () { openFile(item.name); });
      var downBtn = document.createElement("button");
      downBtn.type = "button";
      downBtn.className = "link-btn";
      downBtn.textContent = "下载";
      downBtn.addEventListener("click", function () { openFile(item.name); });
      actions.appendChild(viewBtn);
      actions.appendChild(downBtn);

      tr.appendChild(name);
      tr.appendChild(size);
      tr.appendChild(updated);
      tr.appendChild(actions);
      fileRows.appendChild(tr);
    });
  }

  function applyFilter() {
    var keyword = (searchBox && searchBox.value ? searchBox.value : "").trim().toLowerCase();
    if (!keyword) { renderRows(allFiles); return; }
    renderRows(allFiles.filter(function (item) {
      return String(item.name).toLowerCase().indexOf(keyword) !== -1;
    }));
  }

  function loadFiles() {
    fileRows.innerHTML = "";
    var loading = document.createElement("tr");
    var cell = document.createElement("td");
    cell.colSpan = 4;
    cell.className = "empty";
    cell.textContent = "加载中…";
    loading.appendChild(cell);
    fileRows.appendChild(loading);

    getJSON("/api/files").then(function (data) {
      allFiles = (data && data.files) || [];
      applyFilter();
    }).catch(function () {
      allFiles = [];
      renderRows([]);
      text(previewBody, "无法加载文件列表，请稍后重试。");
    });
  }

  function openFile(name) {
    text(previewName, name);
    text(previewBody, "正在读取…");
    fetch("/api/download?file=" + encodeURIComponent(name), {
      method: "GET",
      headers: { "Accept": "text/plain"}
    }).then(function (res) {
      return res.text();
    }).then(function (body) {
      text(previewBody, body);
    }).catch(function () {
      text(previewBody, "读取失败：该文件当前不可用。");
    });
  }

  function loadAudit() {
    return getJSON("/api/audit").then(function (data) {
      return data;
    }).catch(function () {
      return null;
    });
  }

  loginForm.addEventListener("submit", function (event) {
    event.preventDefault();
    text(loginMsg, "正在验证…");
    loginMsg.classList.remove("ok");

    var payload = {
      username: document.getElementById("username").value,
      password: document.getElementById("password").value
    };

    fetch("/api/login", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Accept": "application/json" },
      body: JSON.stringify(payload)
    }).then(function (res) {
      return res.json().then(function (data) {
        return { status: res.status, data: data };
      });
    }).then(function (result) {
      if (result.status >= 400 || !result.data || result.data.ok === false) {
        text(loginMsg, (result.data && result.data.message) || "账号或密码不正确。");
        return;
      }
      text(loginMsg, "登录成功，正在进入工作台…");
      loginMsg.classList.add("ok");
      currentUser.textContent = result.data.user || payload.username;
      logoutBtn.hidden = false;
      loginView.hidden = true;
      workspaceView.hidden = false;
      loadFiles();
      loadAudit();
    }).catch(function () {
      text(loginMsg, "无法连接认证服务，请检查网络。");
    });
  });

  logoutBtn.addEventListener("click", function () {
    currentUser.textContent = "未登录";
    logoutBtn.hidden = true;
    workspaceView.hidden = true;
    loginView.hidden = false;
    text(loginMsg, "");
    text(previewName, "未选择文件");
    text(previewBody, "请选择左侧“预览”以查看文件内容。");
    loginForm.reset();
  });

  if (reloadBtn) { reloadBtn.addEventListener("click", loadFiles); }
  if (searchBox) { searchBox.addEventListener("input", applyFilter); }
})();
